"""i18n.py — язык ответа службы (владелец 16.11.2026: «переключатель RU / EN»). 16.11.2026.

Язык запроса — заголовок X-Asda-Lang (ru | en), хранится в contextvar на время обработки запроса (потоки службы свои).
  * справочные названия (профессии, карты, навыки, питомцы) refdata отдаёт на этом языке (EN-колонки справочников);
  * сообщения (отказы, ошибки, итоги операций, предпросмотр) служба формирует по-русски, а перед ответом tr() переводит
    их по таблице шаблонов PATTERNS (регулярное выражение по русскому тексту → английский шаблон с группами).
    Нет шаблона — уходит русский текст (так видно, что перевод надо дописать). Интерфейс переводит сам (web/i18n.js).
Побочных эффектов при импорте нет.
"""
import contextvars
import re

LANG = contextvars.ContextVar("asda_lang", default="ru")


def set_lang(v):
    """Язык текущего запроса по заголовку."""
    LANG.set("en" if (v or "").strip().lower().startswith("en") else "ru")


def is_en():
    return LANG.get() == "en"


