def _word(g):
    """Подставленная часть — слово таблицы WORDS целиком (сумка, слот, роль) или список таких через запятую; иначе как есть
    (подстрока внутри имени не заменяется: «Верхний щит» не становится «Верхний shield»)."""
    if g in _WORDS:
        return _WORDS[g]
    parts = g.split(", ")
    return ", ".join(_WORDS[x] for x in parts) if len(parts) > 1 and all(x in _WORDS for x in parts) else g


