def fields(rec):
    """Поля строки журнала для показа: известные тексты видов античита — на языке запроса."""
    if is_en() and isinstance(rec, dict) and isinstance(rec.get("event_kind"), str):
        rec = dict(rec, event_kind=AC_KINDS.get(rec["event_kind"], rec["event_kind"]))
    return rec


_CODE_RX = re.compile(r"\((\d{3,6})\)")


def item_names(msg):
    """«Название (код)» внутри текста → название на языке запроса по справочнику (записи журнала хранят названия
    на языке записи; владелец 16.11: «в английском режиме много предметов по-русски»)."""
    if not is_en() or not isinstance(msg, str) or "(" not in msg:
        return msg
    from domains import refdata
    for code in set(_CODE_RX.findall(msg)):
        inf = refdata.item(int(code))
        if inf["ru"] and inf["en"] and inf["ru"] != inf["en"]:
            msg = msg.replace("%s (%s)" % (inf["ru"], code), "%s (%s)" % (inf["en"], code))
    return msg.replace("без названия (", "no name (")             # перепроверка 5 М5


def tr(msg, _depth=0):
    """Сообщение на языке запроса (EN — по шаблонам; нет шаблона — как есть)."""
    if not is_en() or not isinstance(msg, str) or not msg:
        return msg
    if _depth == 0:
        msg = item_names(msg)
    for rx, en in PATTERNS:
        m = rx.match(msg)
        if m:
            src = rx.pattern[1:-1]
            at = 0 if src in NESTED else NESTED_AT.get(src, NESTED_AT_EXTRA.get(src))
            nested = at is not None and _depth < 4
            plain = src in NAMES
            sub = lambda g: "; ".join(tr(x, _depth + 1) for x in g.split("; "))
            groups = [(sub(g) if nested and i == at else (g if plain else _word(g))) if g else g
                      for i, g in enumerate(m.groups())]
            subs = GROUP_SUBS.get(src)
            if subs:                                   # перепроверка 12 М9: названия профессий в тексте смены профессии
                for i in subs[0]:
                    g = groups[i] or ""
                    for ru, e in subs[1]:
                        g = g.replace(ru, e)
                    groups[i] = g
            return re.sub(r"\\(\d)", lambda x: groups[int(x.group(1)) - 1] or "", en)
    return msg


# ---------------------------------------------------------------------------------------------------------------------
# ★ А3 19.11.2026 «Данные: магазины» (domains/shopdata.py, shopcs.py, shopview.py; api /api/shops/*). Шаблоны записаны в форме
#   printf (как в коде: %s, %d, %X, %.4f, %%) и английской с {0}, {1}…; _a3_rx() превращает их в регулярные выражения таблицы.
#   Порядок: конкретные — В НАЧАЛО таблицы (общие шаблоны других разделов их не перехватят), начинающиеся с подстановки и короткие
#   («нет …», «код …») — В КОНЕЦ (иначе перехватили бы чужие сообщения).
# ---------------------------------------------------------------------------------------------------------------------
def _a3_rx(ru, en):
    rx = re.escape(ru).replace("%%", "%")
    for a, b in (("%s", "(.+)"), ("%d", r"(-?\d+)"), ("%X", "([0-9A-F]+)"), (r"%\.4f", r"([0-9.]+)")):
        rx = rx.replace(a, b)
    return rx, re.sub(r"\{(\d)\}", lambda m: "\\" + str(int(m.group(1)) + 1), en)


