# ★ ревизия 45 В-1: начинающиеся с подстановки «%s…» — в КОНЕЦ таблицы (правило А3: иначе перехватят чужие тексты), прочие — в начало
PATTERNS[:0] = [(re.compile("^" + rx + "$", re.S), en) for rx, en in (_a3_rx(a, b) for a, b in _A5_PATCHCFG if not a.startswith("%"))]
PATTERNS.extend((re.compile("^" + rx + "$", re.S), en) for rx, en in (_a3_rx(a, b) for a, b in _A5_PATCHCFG if a.startswith("%")))
NESTED_AT.update({_a3_rx(a, "")[0]: i for a, i in (
    ("%s [%s] %s — сильная правка: %s", 3), ("зависимый %s выключается этим же набором — %s", 1),
    ("%s включается, а поставщик %s у %s выключен — %s", 3),
    ("[%s] %s=%s — от него зависит включённый %s (%s: %s) — выключите %s этим же набором или оставьте", 5))})

